INSERT INTO diary (diary_id, user_id, title, content, initial_draft, diary_date, analysis, input_type, created_at) VALUES
('d1111111-1111-4111-a111-111111111001', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '첫째 주 시작', '5월의 첫날! 날씨가 너무 좋아서 한강공원으로 자전거를 타러 갔다. 시원한 바람을 맞으니 그동안의 스트레스가 다 날아가는 기분이었다.', '5월의 첫날! 날씨가 너무 좋아서...', '2026-05-01', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111002', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '하이디라오 방문', '오늘 친구랑 같이 하이디라오 훠궈 집에 가서 맛있는 소고기랑 양고기를 엄청 배부르게 먹었다. 직원이 수타면 쇼를 해줬는데 너무 신기하고 재밌었다.', '오늘 친구랑 같이 하이디라오 훠궈 집에 가서...', '2026-05-03', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111003', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '어린이날 휴식', '어린이날이라 늦잠을 푹 잤다. 집에서 넷플릭스 정주행하면서 피자를 시켜 먹었다. 완벽한 집돌이의 하루였다.', '어린이날이라 늦잠을 푹 잤다...', '2026-05-05', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111004', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '야근의 연속', '이번 주는 업무가 폭탄이다. 밤 10시까지 야근을 하고 택시를 타고 집에 왔다. 너무 피곤해서 씻지도 못하고 잠들 뻔했다.', '이번 주는 업무가 폭탄이다...', '2026-05-07', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111005', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '어버이날 식사', '어버이날을 맞아 부모님과 한정식 집에서 식사를 했다. 부모님이 기뻐하시는 모습을 보니 나도 뿌듯하고 행복했다.', '어버이날을 맞아 부모님과 한정식 집에서...', '2026-05-08', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111006', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '운동 시작', '체력이 너무 떨어진 것 같아서 헬스장에 등록했다. 첫 날이라 가볍게 뛰기만 했는데도 다리가 후들거렸다. 꾸준히 해보자!', '체력이 너무 떨어진 것 같아서 헬스장에 등록했다...', '2026-05-11', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111007', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '영화 관람', '기대하던 영화 <어쩔수가없다> 무대인사 회차를 보고 왔다. 감독님과 배우분들 실물이 너무 멋졌고 영화도 정말 여운이 깊게 남았다.', '기대하던 영화 무대인사...', '2026-05-12', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111008', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '책 한 권 다 읽음', '주말을 맞이해 카페에서 소설책을 한 권 다 읽었다. 잔잔한 분위기의 카페에서 책에 온전히 몰입하는 시간이 너무 좋았다.', '주말을 맞이해 카페에서 소설책을...', '2026-05-16', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111009', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '팀 프로젝트 마감', '한 달 동안 준비했던 팀 프로젝트가 드디어 끝났다! 결과물도 좋았고 팀원들과의 회식도 즐거웠다. 해방감 최고!', '한 달 동안 준비했던 팀 프로젝트가 드디어 끝났다...', '2026-05-19', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111010', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '근육통', '며칠 전부터 시작한 헬스 때문에 온몸에 근육통이 왔다. 걷기도 힘들지만 왠지 모를 성취감이 느껴진다.', '며칠 전부터 시작한 헬스 때문에...', '2026-05-21', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111011', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '비오는 날 파전', '오랜만에 비가 주룩주룩 내린다. 퇴근길에 룸메이트랑 파전에 막걸리를 먹기로 했다. 비 오는 날 감성 너무 좋다.', '오랜만에 비가 주룩주룩 내린다...', '2026-05-22', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111012', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '월요병 극복', '월요일에는 유독 일어나기가 힘들었지만, 점심에 동료들과 맛있는 초밥을 먹으며 힘을 냈다. 무사히 하루를 넘겼다.', '월요일에는 유독 일어나기가 힘들었지만...', '2026-05-25', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111013', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '회사에서 실수한 날', '화요일은 업무 중 수치 계산에 큰 실수를 해서 부장님께 크게 혼났다. 자책감이 들고 너무 우울해서 화장실에서 몰래 울었다.', '화요일은 회사에서 큰 실수를...', '2026-05-26', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111014', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '기분 전환 산책', '어제의 우울함을 털어버리려고 저녁 식사 후 1시간 동안 동네를 산책했다. 밤공기가 시원해서 복잡했던 머리가 조금 맑아졌다.', '어제의 우울함을 털어버리려고...', '2026-05-27', '{}', 'MANUAL', NOW()),
('d1111111-1111-4111-a111-111111111015', 'e111e58a-216b-48b6-9084-f43397e5bfaf', '친구들과 불금!', '금요일 퇴근하고 오랜만에 고등학교 친구들을 만나 홍대에서 술을 마셨다. 옛날 얘기도 하고 신나게 웃고 떠들어서 스트레스가 싹 풀렸다!', '금요일 퇴근하고 오랜만에...', '2026-05-29', '{}', 'MANUAL', NOW())
